#include <stdio.h>

/* teste do desafio tabuada — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario escreve num arquivo o que a pessoa "digitaria", aponta o
   stdin para esse arquivo (freopen) e captura o stdout no proprio teste.
   Os nomes dos arquivos temporarios sao POR CENARIO: um cenario nunca le
   a entrada nem a captura do outro. Nunca ha fclose de stdin/stdout — so
   fflush — para o segundo freopen ficar legal (C11 7.21.4). */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void tabuada(void);

SM_TEST(a_tabuada_do_sete) {
    /* o que a pessoa digita: 7 */
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "7\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    /* captura: o stdout vira o arquivo sm_saida_1.tmp */
    freopen("sm_saida_1.tmp", "w", stdout);
    tabuada();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a linha 1 da tabuada do 7", linha, "7 x 1 = 7\n",
              "na volta 1 o contador vale 1 e a conta e 7 x 1");
    fgets(linha, 80, f);
    checa_str("a linha 2 da tabuada do 7", linha, "7 x 2 = 14\n",
              "na volta 2 o contador vale 2 e a conta e 7 x 2");
    fgets(linha, 80, f);
    checa_str("a linha 3 da tabuada do 7", linha, "7 x 3 = 21\n",
              "na volta 3 o contador vale 3 e a conta e 7 x 3");
