    checa_str("a linha 4 da tabuada do 7", linha, "7 x 4 = 28\n",
              "na volta 4 o contador vale 4 e a conta e 7 x 4");
    fgets(linha, 80, f);
    checa_str("a linha 5 da tabuada do 7", linha, "7 x 5 = 35\n",
              "na volta 5 o contador vale 5 e a conta e 7 x 5");
    fgets(linha, 80, f);
    checa_str("a linha 6 da tabuada do 7", linha, "7 x 6 = 42\n",
              "na volta 6 o contador vale 6 e a conta e 7 x 6");
    fgets(linha, 80, f);
    checa_str("a linha 7 da tabuada do 7", linha, "7 x 7 = 49\n",
              "na volta 7 o contador vale 7 e a conta e 7 x 7");
    fgets(linha, 80, f);
